package com.oibsip.onlineexam.service;
import com.oibsip.onlineexam.model.*; import java.time.*; import java.util.*;
public class ExamService {public ExamSession start(List<Question> q){return new ExamSession(q);} public ExamResult submit(ExamSession s,boolean auto){s.submit(auto); int c=0; for(Question q:s.getQuestions())if(s.getAnswers().getOrDefault(q.id(),' ').equals(q.correctAnswer()))c++; int u=s.getQuestions().size()-s.getAnswers().size(); int inc=s.getQuestions().size()-c-u; return new ExamResult(c,c,inc,u,s.getQuestions().size(),s.getQuestions().isEmpty()?0:c*100.0/s.getQuestions().size(),Duration.between(s.getStart(),s.getEnd()),auto,Map.copyOf(s.getAnswers()),s.getQuestions());} public long remainingSeconds(ExamSession s,long duration){return Math.max(0,duration-Duration.between(s.getStart(),Instant.now()).getSeconds());}}
